def next_commands(event, order):
    cost = order["price"] * order["qty"]
    available = event["cash"] - event["reserved"]
    if cost <= available and order["qty"] <= 10:
        return [{"type": "approve"}]
    return []

retry:
def next_commands(event, order):
    if not order["approved"] or order["status"] in ("cancelled", "filled"):
        return []
    if event["kind"] == "submit" or event["kind"] == "timeout":
        return [{"type": "submit", "client_order_id": order["order_id"], "price": order["price"], "qty": order["qty"]}]
    return []
